import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("search and the status filter apply together", { tag: "@LIF-14" }, async ({ factory, apiAs }) => {
  // Arrange: two vendors whose names share one unique word, one draft and one in review.
  const word = uniqueName("Lif14");
  const draft = await factory.vendor({ name: `${word} draft` });
  const review = await factory.vendorInReview({ name: `${word} review` });
  expect(draft.status, "setup: the first vendor is a draft").toBe("draft");
  expect(review.vendor.status, "setup: the second vendor is in review").toBe("in_review");

  // Act: list vendors by the shared word and the in_review status, as a member.
  const member = await apiAs("member");
  const response = await member.get("/api/vendors", { params: { q: word, status: "in_review" } });

  // Assert: only the vendor in review comes back, and the total agrees.
  const page = await expectStatus<{ items: { id: string; status: string }[]; total: number }>(response, 200);
  expect(page.items.map((v) => v.id)).toEqual([review.vendor.id]);
  expect(page.items.every((v) => v.status === "in_review")).toBe(true);
  expect(page.total).toBe(1);
});
